import { useCallback, useEffect, useRef, useState } from 'react';
import { LogOut, Mic, MicOff, Users, Volume2, VolumeX, X } from 'lucide-react';
import type { IAgoraRTCClient, IMicrophoneAudioTrack, IAgoraRTCRemoteUser } from 'agora-rtc-sdk-ng';

const ROOM = 'stooorna-public-voice';
const TALK_MS = 30_000;
const COOLDOWN_MS = 3_000;
const CHIME_FLASH_MS = 2_500;
const LONG_PRESS_MS = 500;
const MIC_SOUND_URL = 'data:audio/mpeg;base64,';

type Peer = {
  id: string;
  uid?: number;
  name: string;
  username?: string | null;
  avatarUrl?: string | null;
  talking?: boolean;
};

type ChatMsg = {
  id: string;
  userId: string;
  name: string;
  text: string;
  at: number;
};

function uidFromString(s: string): number {
  if (!s || s === '0') return 0;
  return Math.abs(s.split('').reduce((a, c) => (Math.imul(31, a) + c.charCodeAt(0)) | 0, 0)) % 100_000 || 1;
}

async function fetchToken(channel: string, userId: string) {
  const r = await fetch(
    `/api/call/token?channel=${encodeURIComponent(channel)}&uid=${encodeURIComponent(userId)}`,
    { credentials: 'include' },
  );
  if (!r.ok) throw new Error('token');
  return r.json() as Promise<{ token: string; uid: number; appId: string }>;
}

export default function PublicVoiceLive({
  userId,
  userName,
  userUsername,
  userAvatar,
  onClose,
}: {
  userId?: string;
  userName?: string;
  userUsername?: string | null;
  userAvatar?: string | null;
  onClose?: () => void;
}) {
  const [peers, setPeers] = useState<Peer[]>([]);
  const [talking, setTalking] = useState(false);
  const [leftMs, setLeftMs] = useState(0);
  const [coolMs, setCoolMs] = useState(0);
  const [mutedIds, setMutedIds] = useState<Set<string>>(new Set());
  const [speakerMuted, setSpeakerMuted] = useState(false);
  const [chimeOff, setChimeOff] = useState(() => {
    try { return localStorage.getItem('pubVoiceChimeOff') === '1'; } catch { return false; }
  });
  const [chimeFlash, setChimeFlash] = useState<'orange' | 'green' | null>(null);
  const [chatOpen, setChatOpen] = useState(true);
  const [membersOpen, setMembersOpen] = useState(false);
  const [chatText, setChatText] = useState('');
  const [chatMsgs, setChatMsgs] = useState<ChatMsg[]>([]);

  const peersRef = useRef<Peer[]>([]);
  const sinceRef = useRef(0);
  const clientRef = useRef<IAgoraRTCClient | null>(null);
  const micRef = useRef<IMicrophoneAudioTrack | null>(null);
  const remoteTracksRef = useRef<Map<number, any>>(new Map());
  const mutedRef = useRef<Set<string>>(new Set());
  const speakerOffRef = useRef(false);
  const myUidRef = useRef(0);
  const talkingRef = useRef(false);
  const playedChimesRef = useRef<Set<string>>(new Set());
  const lastChimeAtRef = useRef(0);
  const chimeOffRef = useRef(false);
  const pressTimerRef = useRef<number | null>(null);
  const chimeFlashTimerRef = useRef<number | null>(null);
  const longPressedRef = useRef(false);
  const chimeAudioRef = useRef<HTMLAudioElement | null>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const chimeBufRef = useRef<AudioBuffer | null>(null);
  const signalPrimedRef = useRef(false);

  const me: Peer = {
    id: String(userId || 'me'),
    name: userName || 'Me',
    username: userUsername || null,
    avatarUrl: userAvatar || null,
    talking,
  };

  const applyMute = useCallback(() => {
    remoteTracksRef.current.forEach((track, uid) => {
      const peer = peersRef.current.find(p => p.uid === uid || uidFromString(p.id) === uid);
      const id = peer?.id || String(uid);
      const off = speakerOffRef.current || mutedRef.current.has(id);
      try {
        if (off) track.stop();
        else track.play();
      } catch {
        /* ignore */
      }
    });
  }, []);

  const sendAgoraChat = useCallback(async (payload: ChatMsg) => {
    const client = clientRef.current;
    try {
      const raw = JSON.stringify({ t: 'chat', ...payload });
      const bytes = new TextEncoder().encode(raw);
      await client?.sendStreamMessage(bytes);
    } catch {
      /* fallback below */
    }
    await fetch('/api/room/signal', {
      method: 'POST',
      credentials: 'include',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        roomId: ROOM,
        t: 'chat',
        data: { t: 'chat', ...payload },
      }),
    }).catch(() => {});
  }, []);

  const playTone = useCallback(() => {
    try {
      const ctx = audioCtxRef.current;
      const buf = chimeBufRef.current;
      if (ctx && buf && ctx.state === 'running') {
        const src = ctx.createBufferSource();
        src.buffer = buf;
        src.connect(ctx.destination);
        src.start(0);
        return;
      }
      if (ctx && ctx.state === 'suspended') void ctx.resume().catch(() => {});
    } catch { /* ignore */ }
    try {
      if (!chimeAudioRef.current) chimeAudioRef.current = new Audio(MIC_SOUND_URL);
      chimeAudioRef.current.volume = 1;
      chimeAudioRef.current.currentTime = 0;
      void chimeAudioRef.current.play().catch(() => {});
    } catch { /* ignore */ }
  }, []);

  const playMicSound = useCallback((id: string) => {
    if (chimeOffRef.current) return;
    if (playedChimesRef.current.has(id)) return;
    playedChimesRef.current.add(id);
    lastChimeAtRef.current = Date.now();
    playTone();
  }, [playTone]);

  // Prepare audio silently (no tone is played when entering the room) and unlock it on the first touch
  useEffect(() => {
    const evs = ['pointerdown', 'touchstart', 'click', 'keydown'];
    const cleanup = () => evs.forEach(e => window.removeEventListener(e, unlock));
    function init() {
      try {
        const AC = (window as any).AudioContext || (window as any).webkitAudioContext;
        if (!AC) return;
        if (!audioCtxRef.current) {
          const ctx: AudioContext = new AC();
          audioCtxRef.current = ctx;
          const bin = atob(MIC_SOUND_URL.split(',')[1]);
          const bytes = new Uint8Array(bin.length);
          for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
          ctx.decodeAudioData(bytes.buffer.slice(0), (buf) => { chimeBufRef.current = buf; }, () => {});
        }
      } catch { /* ignore */ }
    }
    function unlock() {
      init();
      const ctx = audioCtxRef.current;
      if (!ctx) return;
      void ctx.resume().then(() => { if (ctx.state === 'running') cleanup(); }).catch(() => {});
    }
    init();
    evs.forEach(e => window.addEventListener(e, unlock));
    return () => {
      cleanup();
      try { void audioCtxRef.current?.close(); } catch { /* ignore */ }
      audioCtxRef.current = null;
      chimeBufRef.current = null;
    };
  }, []);

  useEffect(() => { chimeOffRef.current = chimeOff; }, [chimeOff]);

  useEffect(() => () => {
    if (pressTimerRef.current) window.clearTimeout(pressTimerRef.current);
    if (chimeFlashTimerRef.current) window.clearTimeout(chimeFlashTimerRef.current);
  }, []);

  const toggleChime = useCallback(() => {
    const next = !chimeOffRef.current;
    chimeOffRef.current = next;
    setChimeOff(next);
    try { localStorage.setItem('pubVoiceChimeOff', next ? '1' : '0'); } catch { /* ignore */ }
    setChimeFlash(next ? 'orange' : 'green');
    if (chimeFlashTimerRef.current) window.clearTimeout(chimeFlashTimerRef.current);
    chimeFlashTimerRef.current = window.setTimeout(() => {
      setChimeFlash(null);
      chimeFlashTimerRef.current = null;
    }, CHIME_FLASH_MS);
    if (!next) {
      // Chime turned back on: play it once as confirmation
      playTone();
    }
  }, [playTone]);

  const pressStart = useCallback(() => {
    longPressedRef.current = false;
    if (pressTimerRef.current) window.clearTimeout(pressTimerRef.current);
    pressTimerRef.current = window.setTimeout(() => {
      longPressedRef.current = true;
      toggleChime();
    }, LONG_PRESS_MS);
  }, [toggleChime]);

  const pressEnd = useCallback(() => {
    if (pressTimerRef.current) { window.clearTimeout(pressTimerRef.current); pressTimerRef.current = null; }
  }, []);

  const sendMicSound = useCallback(async () => {
    // Chime is off: do not play it locally and do not broadcast it to listeners
    if (chimeOffRef.current) return;
    const payload = { t: 'mic-sound', id: `ms-${userId}-${Date.now()}`, userId: String(userId || ''), at: Date.now() };
    playMicSound(payload.id);
    try {
      const bytes = new TextEncoder().encode(JSON.stringify(payload));
      await clientRef.current?.sendStreamMessage(bytes);
    } catch { /* fallback below */ }
    await fetch('/api/room/signal', {
      method: 'POST',
      credentials: 'include',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ roomId: ROOM, t: 'chat', data: payload }),
    }).catch(() => {});
  }, [userId, playMicSound]);

  const stopMic = useCallback(() => {
    talkingRef.current = false;
    setTalking(false);
    setLeftMs(0);
    const mic = micRef.current;
    if (mic) {
      try { mic.setMuted(true); } catch { /* ignore */ }
    }
    void fetch('/api/room/floor', {
      method: 'POST',
      credentials: 'include',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ roomId: ROOM, userId, talking: false }),
    }).catch(() => {});
  }, [userId]);

  const startMic = useCallback(async () => {
    if (coolMs > 0 || talkingRef.current || !userId) return;
    const mic = micRef.current;
    if (!mic) return;
    try {
      await mic.setEnabled(true);
      try { mic.setMuted(false); } catch { /* ignore */ }
      talkingRef.current = true;
      setTalking(true);
      setLeftMs(TALK_MS);
      void sendMicSound();
      await fetch('/api/room/floor', {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ roomId: ROOM, userId, talking: true }),
      }).catch(() => {});
    } catch {
      talkingRef.current = false;
      setTalking(false);
    }
  }, [coolMs, userId, sendMicSound]);

  useEffect(() => {
    if (!talking) return;
    const t0 = Date.now();
    const id = window.setInterval(() => {
      const left = TALK_MS - (Date.now() - t0);
      if (left <= 0) {
        stopMic();
        setCoolMs(COOLDOWN_MS);
      } else setLeftMs(left);
    }, 200);
    return () => window.clearInterval(id);
  }, [talking, stopMic]);

  useEffect(() => {
    if (coolMs <= 0) return;
    const t0 = Date.now();
    const start = coolMs;
    const id = window.setInterval(() => setCoolMs(Math.max(0, start - (Date.now() - t0))), 200);
    return () => window.clearInterval(id);
  }, [coolMs > 0]);

  useEffect(() => {
    try {
      window.dispatchEvent(new CustomEvent('stooorna:live-map', { detail: { open: true } }));
    } catch { /* ignore */ }
    return () => {
      try {
        window.dispatchEvent(new CustomEvent('stooorna:live-map', { detail: { open: false } }));
      } catch { /* ignore */ }
    };
  }, []);

  useEffect(() => {
    if (!userId) return;
    let stop = false;
    (async () => {
      try {
        const AgoraRTC = (await import('agora-rtc-sdk-ng')).default;
        AgoraRTC.setLogLevel(3);
        const { token, uid, appId } = await fetchToken(ROOM, userId);
        myUidRef.current = uid || uidFromString(userId);
        const client = AgoraRTC.createClient({ mode: 'rtc', codec: 'vp8' });
        clientRef.current = client;

        client.on('user-published', async (remoteUser: IAgoraRTCRemoteUser, mediaType: string) => {
          if (mediaType !== 'audio') return;
          try {
            await client.subscribe(remoteUser, 'audio');
            const track = remoteUser.audioTrack;
            if (track) {
              remoteTracksRef.current.set(remoteUser.uid as number, track);
              applyMute();
            }
          } catch { /* ignore */ }
        });
        client.on('user-unpublished', (remoteUser: IAgoraRTCRemoteUser, mediaType: string) => {
          if (mediaType === 'audio') {
            remoteUser.audioTrack?.stop();
            remoteTracksRef.current.delete(remoteUser.uid as number);
          }
        });
        client.on('user-left', (remoteUser: IAgoraRTCRemoteUser) => {
          remoteUser.audioTrack?.stop();
          remoteTracksRef.current.delete(remoteUser.uid as number);
        });
        const onStream = (...args: any[]) => {
          try {
            let data: any = args.length >= 2 ? args[1] : args[0];
            if (data && typeof data === 'object' && 'data' in data && !(data instanceof ArrayBuffer)) data = data.data;
            let raw = '';
            if (typeof data === 'string') raw = data;
            else if (data instanceof ArrayBuffer) raw = new TextDecoder().decode(new Uint8Array(data));
            else if (ArrayBuffer.isView(data)) raw = new TextDecoder().decode(data as Uint8Array);
            raw = raw.replace(/\u0000/g, '').trim();
            if (!raw) return;
            const msg = JSON.parse(raw);
            if (msg?.t === 'mic-sound' && msg.id) {
              if (String(msg.userId) !== String(userId) && !speakerOffRef.current) playMicSound(String(msg.id));
              return;
            }
            if (msg?.t !== 'chat' || !msg.text) return;
            setChatMsgs(prev => {
              if (prev.some(x => x.id === String(msg.id))) return prev;
              return [...prev, {
                id: String(msg.id),
                userId: String(msg.userId || ''),
                name: String(msg.name || 'User'),
                text: String(msg.text),
                at: Number(msg.at || Date.now()),
              }].slice(-80);
            });
          } catch { /* ignore */ }
        };
        client.on('stream-message', onStream);
        try { (client as any).on('streamMessage', onStream); } catch { /* ignore */ }

        await client.join(appId, ROOM, token, myUidRef.current);
        const mic = await AgoraRTC.createMicrophoneAudioTrack({
          encoderConfig: { sampleRate: 48000, stereo: false, bitrate: 48 },
          AEC: true,
          ANS: true,
          AGC: true,
        });
        micRef.current = mic;
        await mic.setEnabled(true);
        try { mic.setMuted(true); } catch { /* ignore */ }
        await client.publish([mic]);
      } catch {
        /* token/join optional if server down */
      }

      await fetch('/api/room/join', {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          roomId: ROOM,
          userId,
          name: userName,
          username: userUsername,
          avatarUrl: userAvatar,
        }),
      }).catch(() => {});
    })();

    const pull = async () => {
      if (stop) return;
      try {
        const r = await fetch(`/api/room?id=${encodeURIComponent(ROOM)}`, { credentials: 'include' });
        if (r.ok) {
          const d = await r.json();
          const members = (d.members || d.users || []) as any[];
          const nextPeers = members
            .map(m => ({
              id: String(m.id || m.userId || ''),
              uid: Number(m.uid || uidFromString(String(m.id || m.userId || ''))),
              name: String(m.name || m.username || 'User'),
              username: m.username ?? null,
              avatarUrl: m.avatarUrl ?? m.image ?? null,
              talking: !!(m.talking || m.floor),
            }))
            .filter(p => p.id);
          peersRef.current = nextPeers;
          setPeers(nextPeers);
        }
      } catch { /* ignore */ }
      try {
        const r = await fetch(`/api/room/signal?roomId=${encodeURIComponent(ROOM)}&since=${sinceRef.current}`, { credentials: 'include' });
        if (!r.ok) return;
        const d = await r.json();
        const items = (d.items || d.signals || []) as any[];
        for (const raw of items) {
          const msg = raw?.data || raw;
          const at = Number(raw.at || msg.at || Date.now());
          if (at > sinceRef.current) sinceRef.current = at;
          if (msg?.t === 'mic-sound' && msg.id) {
            if (!signalPrimedRef.current) {
              // Old signals from before joining: never play them
              playedChimesRef.current.add(String(msg.id));
              continue;
            }
            if (String(msg.userId) !== String(userId) && !speakerOffRef.current) playMicSound(String(msg.id));
            continue;
          }
          if (msg?.t !== 'chat' || !msg.text) continue;
          setChatMsgs(prev => {
            if (prev.some(x => x.id === String(msg.id))) return prev;
            return [...prev, {
              id: String(msg.id || `${msg.userId}-${at}`),
              userId: String(msg.userId || ''),
              name: String(msg.name || 'User'),
              text: String(msg.text),
              at,
            }].slice(-80);
          });
        }
      } catch { /* ignore */ }
      signalPrimedRef.current = true;
    };
    void pull();
    const id = window.setInterval(pull, 1800);
    return () => {
      stop = true;
      window.clearInterval(id);
      stopMic();
      try { micRef.current?.stop(); micRef.current?.close(); } catch { /* ignore */ }
      micRef.current = null;
      try { clientRef.current?.leave(); } catch { /* ignore */ }
      clientRef.current = null;
      remoteTracksRef.current.forEach(t => { try { t.stop(); } catch { /* */ } });
      remoteTracksRef.current.clear();
      void fetch('/api/room/leave', {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ roomId: ROOM, userId }),
      }).catch(() => {});
    };
  }, [userId, userName, userUsername, userAvatar, applyMute, stopMic, playMicSound]);

  function toggleMute(id: string) {
    if (id === me.id) return;
    setMutedIds(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      mutedRef.current = next;
      applyMute();
      return next;
    });
  }

  async function sendChat() {
    const text = chatText.trim();
    if (!text || !userId) return;
    setChatText('');
    const msg: ChatMsg = {
      id: `${userId}-${Date.now()}`,
      userId,
      name: userUsername ? `@${String(userUsername).replace(/^@/, '')}` : (userName || 'Me'),
      text,
      at: Date.now(),
    };
    setChatMsgs(prev => [...prev, msg].slice(-80));
    await sendAgoraChat(msg);
  }

  const list = [me, ...peers.filter(p => p.id !== me.id)];
  const secs = Math.ceil(leftMs / 1000);
  const cool = Math.ceil(coolMs / 1000);

  return (
    <div
      style={{
        position: 'fixed',
        inset: 0,
        zIndex: 14000,
        background: 'radial-gradient(ellipse 70% 50% at 50% 0%, #132226 0%, #070f10 55%)',
        display: 'flex',
        flexDirection: 'column',
        color: '#d7eeee',
      }}
    >
      <style>{`
        @keyframes pubVoicePulse {
          0% { transform: scale(0.55); opacity: 0.7; }
          70% { transform: scale(1); opacity: 0; }
          100% { transform: scale(1); opacity: 0; }
        }
      `}</style>

      <div style={{ padding: '8px 10px', display: 'flex', alignItems: 'center', gap: 6 }}>
        <div style={{ flex: 1, minWidth: 0 }}>
          <p style={{ margin: 0, fontWeight: 800, color: '#00BCD4', fontSize: 13 }}>Public Voice</p>
          <p style={{ margin: 0, fontSize: 10, color: 'rgba(150,200,200,0.65)' }}>Shared room</p>
        </div>
        <button
          type="button"
          onClick={() => setMembersOpen(true)}
          style={{
            display: 'flex', alignItems: 'center', gap: 4, color: 'rgba(150,200,200,0.9)',
            fontSize: 11, fontWeight: 700, padding: '3px 8px', borderRadius: 14,
            background: membersOpen ? 'rgba(0,188,212,0.22)' : 'rgba(0,188,212,0.1)',
            border: '1px solid rgba(0,188,212,0.3)', cursor: 'pointer',
          }}
        >
          <Users size={11} />
          <span>{list.length}</span>
        </button>
        <button
          type="button"
          onClick={onClose}
          style={{
            width: 28, height: 28, borderRadius: '50%', cursor: 'pointer',
            background: 'rgba(239,68,68,0.16)', border: '1px solid rgba(239,68,68,0.45)',
            color: '#ef4444', display: 'flex', alignItems: 'center', justifyContent: 'center',
          }}
        >
          <LogOut size={13} />
        </button>
      </div>

      <div style={{ display: 'flex', gap: 8, overflowX: 'auto', padding: '2px 10px 8px' }}>
        {list.map(p => {
          const muted = mutedIds.has(p.id) || speakerMuted;
          const isTalk = !!p.talking;
          const ring = isTalk ? '#22c55e' : muted && p.id !== me.id ? '#6b7280' : 'rgba(0,188,212,0.35)';
          return (
            <button
              key={p.id}
              type="button"
              onClick={() => toggleMute(p.id)}
              style={{ width: 56, flexShrink: 0, background: 'none', border: 'none', color: 'inherit', padding: 0, cursor: p.id === me.id ? 'default' : 'pointer' }}
            >
              <div style={{
                width: 42, height: 42, margin: '0 auto', borderRadius: '50%', overflow: 'hidden',
                border: `2px solid ${ring}`, background: '#102226',
                opacity: muted && p.id !== me.id ? 0.5 : 1,
                boxShadow: isTalk ? '0 0 8px rgba(34,197,94,0.55)' : 'none',
              }}>
                {p.avatarUrl ? (
                  <img src={p.avatarUrl} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                ) : (
                  <div style={{ width: '100%', height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#00BCD4', fontWeight: 800, fontSize: 13 }}>
                    {(p.name || '?')[0]}
                  </div>
                )}
              </div>
              <p style={{ margin: '4px 0 0', fontSize: 9, fontWeight: 700, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                {p.username ? `@${String(p.username).replace(/^@/, '')}` : p.name}
              </p>
            </button>
          );
        })}
      </div>

      <div style={{ flex: 1, minHeight: 0, position: 'relative' }}>
        {chatOpen && (
          <div style={{
            position: 'absolute', left: 8, right: 8, bottom: 6, maxHeight: 168,
            background: 'rgba(4,14,16,0.88)', border: '1px solid rgba(0,188,212,0.18)',
            borderRadius: 12, padding: '6px 8px', display: 'flex', flexDirection: 'column', gap: 5,
          }}>
            <div style={{ flex: 1, overflowY: 'auto', minHeight: 36, display: 'flex', flexDirection: 'column', gap: 3 }}>
              {chatMsgs.length === 0 && (
                <p style={{ margin: 0, color: 'rgba(150,200,200,0.4)', fontSize: 11 }}>Live chat</p>
              )}
              {chatMsgs.map(m => (
                <p key={m.id} style={{ margin: 0, fontSize: 11, lineHeight: 1.3, color: m.userId === userId ? '#00BCD4' : 'rgba(220,240,240,0.9)' }}>
                  <span style={{ fontWeight: 800, color: m.userId === userId ? '#00BCD4' : '#eab308' }}>{m.name} </span>
                  {m.text}
                </p>
              ))}
            </div>
            <div style={{ display: 'flex', gap: 5, alignItems: 'center' }}>
              <input
                value={chatText}
                onChange={e => setChatText(e.target.value)}
                onKeyDown={e => { if (e.key === 'Enter') void sendChat(); }}
                placeholder="Message"
                style={{
                  flex: 1, height: 30, borderRadius: 16, border: '1px solid rgba(0,188,212,0.25)',
                  background: 'rgba(0,20,24,0.8)', color: '#d7eeee', padding: '0 10px', outline: 'none', fontSize: 12,
                }}
              />
              <button
                type="button"
                onClick={() => void sendChat()}
                style={{
                  height: 30, border: 'none', borderRadius: 16, padding: '0 10px', fontWeight: 800, fontSize: 11,
                  background: '#00BCD4', color: '#041414', cursor: 'pointer',
                }}
              >
                Send
              </button>
            </div>
          </div>
        )}
      </div>

      <div style={{
        padding: '6px 10px max(10px, env(safe-area-inset-bottom))',
        display: 'flex',
        alignItems: 'center',
        gap: 8,
      }}>
        <button
          type="button"
          onClick={() => setChatOpen(o => !o)}
          style={{
            border: '1px solid rgba(0,188,212,0.28)', background: 'rgba(6,16,18,0.85)',
            color: '#00BCD4', borderRadius: 999, padding: '4px 8px', fontSize: 10, fontWeight: 800, cursor: 'pointer',
          }}
        >
          {chatOpen ? 'Hide' : 'Chat'}
        </button>
        <div style={{ flex: 1, display: 'flex', justifyContent: 'center' }}>
          <button
            type="button"
            onClick={() => {
              if (longPressedRef.current) { longPressedRef.current = false; return; }
              if (coolMs > 0) return;
              if (talking) stopMic(); else startMic();
            }}
            onPointerDown={pressStart}
            onPointerUp={pressEnd}
            onPointerLeave={pressEnd}
            onPointerCancel={pressEnd}
            onContextMenu={e => e.preventDefault()}
            aria-disabled={coolMs > 0}
            style={{
              position: 'relative',
              width: 46,
              height: 46,
              borderRadius: '50%',
              border: talking ? '2px solid #ef4444' : '1px solid rgba(0,188,212,0.35)',
              background: talking ? 'rgba(239,68,68,0.22)' : 'rgba(0,188,212,0.1)',
              color: talking ? '#ef4444' : coolMs > 0 ? '#6b7280' : '#00BCD4',
              cursor: coolMs > 0 ? 'default' : 'pointer',
              overflow: 'hidden',
              touchAction: 'none',
              userSelect: 'none',
              WebkitUserSelect: 'none',
              WebkitTouchCallout: 'none',
              WebkitTapHighlightColor: 'transparent',
            }}
          >
            {chimeFlash && (
              <span
                style={{
                  position: 'absolute', inset: 0, borderRadius: '50%', zIndex: 2, pointerEvents: 'none',
                  background: chimeFlash === 'orange' ? 'rgba(249,115,22,0.6)' : 'rgba(34,197,94,0.6)',
                  border: `2px solid ${chimeFlash === 'orange' ? '#f97316' : '#22c55e'}`,
                  animation: `pubVoiceChimeFlash ${CHIME_FLASH_MS}ms ease-out forwards`,
                }}
              />
            )}
            <style>{'@keyframes pubVoiceChimeFlash{0%{opacity:1}75%{opacity:1}100%{opacity:0}}'}</style>
            {talking && (
              <>
                <span style={{ position: 'absolute', inset: 4, borderRadius: '50%', border: '2px solid rgba(239,68,68,0.55)', animation: 'pubVoicePulse 1s ease-out infinite' }} />
                <span style={{ position: 'absolute', inset: 8, borderRadius: '50%', border: '2px solid rgba(239,68,68,0.4)', animation: 'pubVoicePulse 1s ease-out infinite 0.25s' }} />
              </>
            )}
            <span style={{ position: 'relative', zIndex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              {talking ? <Mic size={16} /> : <MicOff size={16} />}
            </span>
          </button>
        </div>
        <button
          type="button"
          onClick={() => setSpeakerMuted(v => {
            const next = !v;
            speakerOffRef.current = next;
            applyMute();
            return next;
          })}
          style={{
            height: 28, padding: '0 8px', borderRadius: 10,
            border: speakerMuted ? '1px solid rgba(239,68,68,0.4)' : '1px solid rgba(0,188,212,0.28)',
            background: speakerMuted ? 'rgba(239,68,68,0.12)' : 'rgba(0,188,212,0.08)',
            color: speakerMuted ? '#ef4444' : '#00BCD4', cursor: 'pointer', fontSize: 10, fontWeight: 700,
            display: 'flex', alignItems: 'center', gap: 4,
          }}
        >
          {speakerMuted ? <VolumeX size={12} /> : <Volume2 size={12} />}
          {speakerMuted ? 'Unmute' : 'Mute'}
        </button>
      </div>
      <p style={{ margin: '0 0 6px', fontSize: 10, color: 'rgba(150,200,200,0.45)', textAlign: 'center' }}>
        {talking ? `${secs}s` : coolMs > 0 ? `Wait ${cool}s` : '30s turns'}
      </p>

      {membersOpen && (
        <div
          onClick={() => setMembersOpen(false)}
          style={{ position: 'fixed', inset: 0, zIndex: 20, background: 'rgba(0,0,0,0.55)' }}
        >
          <div
            onClick={e => e.stopPropagation()}
            style={{
              position: 'absolute', left: 0, right: 0, bottom: 0,
              maxHeight: '70%', overflowY: 'auto',
              background: 'linear-gradient(180deg, #0c1c1f 0%, #071112 100%)',
              borderTop: '1px solid rgba(0,188,212,0.25)',
              borderRadius: '16px 16px 0 0',
              padding: '12px 12px max(16px, env(safe-area-inset-bottom))',
            }}
          >
            <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 10 }}>
              <Users size={14} color="#00BCD4" />
              <p style={{ margin: 0, flex: 1, fontWeight: 800, color: '#00BCD4', fontSize: 13 }}>In room · {list.length}</p>
              <button type="button" onClick={() => setMembersOpen(false)} style={{ background: 'none', border: 'none', color: '#00BCD4', cursor: 'pointer' }}>
                <X size={16} />
              </button>
            </div>
            {list.map(p => {
              const muted = mutedIds.has(p.id);
              return (
                <button
                  key={p.id}
                  type="button"
                  onClick={() => toggleMute(p.id)}
                  style={{
                    width: '100%', display: 'flex', alignItems: 'center', gap: 10,
                    padding: '8px 4px', background: 'none', border: 'none', color: 'inherit',
                    cursor: p.id === me.id ? 'default' : 'pointer',
                  }}
                >
                  <div style={{
                    width: 36, height: 36, borderRadius: '50%', overflow: 'hidden', flexShrink: 0,
                    border: `2px solid ${p.talking ? '#22c55e' : muted ? '#6b7280' : 'rgba(0,188,212,0.35)'}`,
                  }}>
                    {p.avatarUrl ? <img src={p.avatarUrl} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} /> : null}
                  </div>
                  <span style={{ flex: 1, textAlign: 'left', fontSize: 13, fontWeight: 700 }}>
                    {p.username ? `@${String(p.username).replace(/^@/, '')}` : p.name}
                  </span>
                  {p.id !== me.id && <span style={{ fontSize: 11, color: muted ? '#ef4444' : '#22c55e' }}>{muted ? 'Muted' : 'Live'}</span>}
                </button>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}
